// Shop.mn-ий өгөгдлийн сангаас асуух асуултууд.
// Query бүр доорх хүснэгт болж харагдана.

window.QUERIES = {
  named: {
    title: "Ангилалын нэртэйгээр",
    sql: `
    SELECT categories.name AS ангилал, products.name AS бараа, products.price
    FROM products
    JOIN categories ON categories.id = products.category_id
    ORDER BY categories.name, products.price DESC;
    `,
  },

  revenue: {
    title: "Хэрэглэгч тус бүрийн худалдан авалт",
    sql: `
    SELECT customers.name AS хэрэглэгч,
           SUM(products.price * order_items.quantity) AS нийт
    FROM order_items
    JOIN orders ON orders.id = order_items.order_id
    JOIN customers ON customers.id = orders.customer_id
    JOIN products ON products.id = order_items.product_id
    GROUP BY customers.id
    ORDER BY нийт DESC;
    `,
  },
};
